import os
import sys
import time
from datetime import datetime, timedelta
from typing import Dict, List, Tuple

class TokenManager:
    def __init__(self, state_dir: str):
        self.state_dir = state_dir
        self.state_file = os.path.join(state_dir, "state")
        self.tokens: Dict[str, Dict] = {}
        self.client_issuance_times: Dict[str, List[float]] = {}
        self.load_state()

    def load_state(self):
        if os.path.exists(self.state_file):
            with open(self.state_file, "r") as f:
                for line in f:
                    parts = line.strip().split("|")
                    if len(parts) == 4:
                        token, username, issuance_time, expiry_time = parts
                        self.tokens[token] = {
                            "username": username,
                            "issuance_time": float(issuance_time),
                            "expiry_time": float(expiry_time),
                            "redeemed": False
                        }
                        client_id = f"client_{issuance_time}"
                        if client_id not in self.client_issuance_times:
                            self.client_issuance_times[client_id] = []
                        self.client_issuance_times[client_id].append(float(issuance_time))

    def save_state(self):
        with open(self.state_file, "w") as f:
            for token, data in self.tokens.items():
                f.write(f"{token}|{data['username']}|{data['issuance_time']}|{data['expiry_time']}\n")

    def issue_token(self, client_id: str, username: str) -> str:
        current_time = time.time()
        client_key = f"client_{current_time}"

        if client_id in self.client_issuance_times:
            issuance_times = self.client_issuance_times[client_id]
            recent_issuances = [t for t in issuance_times if t >= current_time - 60]
            if len(recent_issuances) >= 3:
                return f"throttled {client_id}"

        # Generate a 32-character token
        import random
        chars = "A-Za-z0-9"
        token = ''.join(random.choice(chars) for _ in range(32))

        expiry_time = current_time + 900
        self.tokens[token] = {
            "username": username,
            "issuance_time": current_time,
            "expiry_time": expiry_time,
            "redeemed": False
        }

        if client_id not in self.client_issuance_times:
            self.client_issuance_times[client_id] = []
        self.client_issuance_times[client_id].append(current_time)

        return f"<p>{username}: <a href=\"/confirm?token={token}\">{token}</a></p>"

    def redeem_token(self, token: str) -> str:
        if token not in self.tokens:
            return "invalid"

        data = self.tokens[token]
        if data["redeemed"]:
            return "invalid"

        if data["expiry_time"] < time.time():
            return "invalid"

        data["redeemed"] = True
        return f"ok {data['username']}"

