import os
import sys
import time
import json
from datetime import datetime, timedelta

class TokenManager:
    def __init__(self, state_dir):
        self.state_dir = state_dir
        self.client_throttle = {}
        self.tokens = {}
        self._load_state()

    def _load_state(self):
        if not os.path.exists(self.state_dir):
            os.makedirs(self.state_dir)
        state_path = os.path.join(self.state_dir, 'state')
        if os.path.exists(state_path):
            with open(state_path, 'r') as f:
                self.tokens = json.load(f)

    def _save_state(self):
        state_path = os.path.join(self.state_dir, 'state')
        with open(state_path, 'w') as f:
            json.dump(self.tokens, f)

    def issue_token(self, client_id, username):
        now = time.time()
        if client_id in self.client_throttle:
            last_issued = self.client_throttle[client_id]
            if now - last_issued < 60:
                return False
            self.client_throttle[client_id] = now
        else:
            self.client_throttle[client_id] = now

        if client_id in self.client_throttle and (now - self.client_throttle[client_id]) < 60 and len(self.client_throttle[client_id]) >= 3:
            return False

        token = ''.join([chr((ord('A') + i) % 62) for i in range(32)])
        expiry = now + 900
        self.tokens[token] = {
            'username': username,
            'issued': now,
            'expiry': expiry,
            'redeemed': False
        }
        self._save_state()
        return token

    def redeem_token(self, token):
        if token in self.tokens:
            token_data = self.tokens[token]
            if not token_data['redeemed'] and token_data['expiry'] > time.time():
                token_data['redeemed'] = True
                self._save_state()
                return token_data['username']
        return None

