import os
import time
import random
import string
from datetime import datetime, timedelta

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

class TokenManager:
    def __init__(self, state_dir):
        self.state_dir = state_dir
        self.state_file = os.path.join(state_dir, 'state')
        self.tokens = {}
        self.client_issues = {}
        self.load_state()

    def load_state(self):
        if os.path.exists(self.state_file):
            with open(self.state_file, 'r') as f:
                for line in f:
                    parts = line.strip().split()
                    if len(parts) == 5:
                        token, username, issue_time, expiry_time, redeemed = parts
                        self.tokens[token] = {
                            'username': username,
                            'issue_time': int(issue_time),
                            'expiry_time': int(expiry_time),
                            'redeemed': redeemed == 'True'
                        }
                    elif len(parts) == 4:
                        client_id, username, issue_time, expiry_time = parts
                        self.client_issues[client_id] = {
                            'username': username,
                            'issue_time': int(issue_time),
                            'expiry_time': int(expiry_time)
                        }

    def save_state(self):
        with open(self.state_file, 'w') as f:
            for token, data in self.tokens.items():
                f.write(f"{token} {data['username']} {data['issue_time']} {data['expiry_time']} {'True' if data['redeemed'] else 'False'}\n")
            for client_id, data in self.client_issues.items():
                f.write(f"{client_id} {data['username']} {data['issue_time']} {data['expiry_time']}\n")

    def issue_token(self, client_id, username):
        current_time = time.time()
        if client_id in self.client_issues:
            issues = self.client_issues[client_id]
            if len(issues) >= 3:
                last_issue = max(issue['issue_time'] for issue in issues)
                if current_time - last_issue < 60:
                    return None
            self.client_issues[client_id].append({
                'username': username,
                'issue_time': current_time,
                'expiry_time': current_time + 900
            })
        else:
            self.client_issues[client_id] = [{
                'username': username,
                'issue_time': current_time,
                'expiry_time': current_time + 900
            }]

        token = generate_token()
        self.tokens[token] = {
            'username': username,
            'issue_time': current_time,
            'expiry_time': current_time + 900,
            'redeemed': False
        }
        return token

    def redeem_token(self, token):
        if token in self.tokens:
            data = self.tokens[token]
            if not data['redeemed'] and data['expiry_time'] > time.time():
                data['redeemed'] = True
                return data['username']
        return None

def main(state_dir):
    manager = TokenManager(state_dir)
    while True:
        try:
            line = input().strip()
            if not line:
                continue
            parts = line.split()
