                token = manager.issue_token(client_id, username)
                if token:
                    expiry_time = manager.tokens[token]['expiry_time']
                    print(f"<p>{username}: <a href=\"/confirm?token={token}\">{token}</a></p>")
                else:
                    print(f"throttled {client_id}")
            elif parts[0] == 'redeem':
                if len(parts) != 2:
